import{_ as o,c as i,o as r,ag as t}from"./chunks/framework.ymCRTBvy.js";const p=JSON.parse('{"title":"4.1 UIViewController生命周期详解","description":"","frontmatter":{},"headers":[],"relativePath":"swift/uikit/uikit_networking_persistence/4.1_UIViewController生命周期详解.md","filePath":"swift/uikit/uikit_networking_persistence/4.1_UIViewController生命周期详解.md"}'),l={name:"swift/uikit/uikit_networking_persistence/4.1_UIViewController生命周期详解.md"};function a(n,e,d,c,s,u){return r(),i("div",null,e[0]||(e[0]=[t('<h1 id="_4-1-uiviewcontroller生命周期详解" tabindex="-1">4.1 UIViewController生命周期详解 <a class="header-anchor" href="#_4-1-uiviewcontroller生命周期详解" aria-label="Permalink to &quot;4.1 UIViewController生命周期详解&quot;">​</a></h1><h2 id="uiviewcontroller生命周期概览-🚀" tabindex="-1">UIViewController生命周期概览 🚀 <a class="header-anchor" href="#uiviewcontroller生命周期概览-🚀" aria-label="Permalink to &quot;UIViewController生命周期概览 🚀&quot;">​</a></h2><p>每个<code>UIViewController</code>都有一个明确的生命周期，理解它对于构建健壮的iOS应用至关重要。从视图加载到视图卸载，每个阶段都有其特定的用途和最佳实践。掌握这些，你就能更有效地管理资源和用户体验。</p><h2 id="视图加载阶段-从初始化到显示-✨" tabindex="-1">视图加载阶段：从初始化到显示 ✨ <a class="header-anchor" href="#视图加载阶段-从初始化到显示-✨" aria-label="Permalink to &quot;视图加载阶段：从初始化到显示 ✨&quot;">​</a></h2><p>当一个<code>UIViewController</code>被创建并准备显示其视图时，会经历一系列重要的步骤。这个过程从初始化开始，逐步构建视图层次结构，直到视图完全呈现在屏幕上。</p><ul><li><strong><code>init(nibName:bundle:)</code> 或 <code>init()</code></strong>: 这是控制器被创建的起点。如果你使用代码创建控制器，通常会调用<code>init()</code>。如果你从Storyboard或XIB加载，系统会调用<code>init(nibName:bundle:)</code>。</li><li><strong><code>loadView()</code></strong>: 这个方法负责创建或加载控制器的根视图。如果你没有在Storyboard或XIB中指定视图，系统会为你创建一个空的<code>UIView</code>。你也可以重写此方法来手动创建自定义视图。</li><li><strong><code>viewDidLoad()</code></strong>: 视图加载完成后，系统会调用此方法。这是执行一次性设置的理想位置，例如配置UI元素、加载数据或设置通知。请记住，此时视图的几何形状尚未最终确定。</li></ul><blockquote><p>💡 统计数据显示，大约80%的UI初始化工作都在<code>viewDidLoad()</code>中完成，因为它确保了视图在内存中且可用。</p></blockquote><h2 id="视图显示阶段-即将出现与已出现-🌟" tabindex="-1">视图显示阶段：即将出现与已出现 🌟 <a class="header-anchor" href="#视图显示阶段-即将出现与已出现-🌟" aria-label="Permalink to &quot;视图显示阶段：即将出现与已出现 🌟&quot;">​</a></h2><p>视图加载完毕后，它会经历即将显示和已经显示的阶段。这些方法在视图即将出现在屏幕上或已经完全显示时被调用，非常适合执行与视图可见性相关的任务。</p><ul><li><strong><code>viewWillAppear(_ animated: Bool)</code></strong>: 在视图即将添加到视图层次结构中并显示给用户之前调用。你可以在这里执行一些轻量级的更新，例如刷新数据或启动动画。</li><li><strong><code>viewDidAppear(_ animated: Bool)</code></strong>: 在视图已经完全显示在屏幕上之后调用。这是启动耗时操作、动画或网络请求的绝佳时机，因为此时用户已经可以看到视图。</li><li><strong><code>viewWillLayoutSubviews()</code></strong>: 在控制器的视图即将调整其子视图布局时调用。如果你需要根据新的布局调整子视图，可以在这里进行。</li><li><strong><code>viewDidLayoutSubviews()</code></strong>: 在控制器的视图已经调整完其子视图布局后调用。这是在布局完成后进行最终调整的好地方。</li></ul><h2 id="视图消失阶段-即将消失与已消失-🌙" tabindex="-1">视图消失阶段：即将消失与已消失 🌙 <a class="header-anchor" href="#视图消失阶段-即将消失与已消失-🌙" aria-label="Permalink to &quot;视图消失阶段：即将消失与已消失 🌙&quot;">​</a></h2><p>当视图不再可见时，也会触发一系列方法。这些方法允许你在视图离开屏幕时执行清理工作或暂停活动。</p><ul><li><strong><code>viewWillDisappear(_ animated: Bool)</code></strong>: 在视图即将从视图层次结构中移除或被其他视图覆盖之前调用。你可以在这里保存用户数据、停止正在进行的任务或取消网络请求。</li><li><strong><code>viewDidDisappear(_ animated: Bool)</code></strong>: 在视图已经完全从屏幕上消失之后调用。这是执行更彻底清理的理想位置，例如释放不再需要的资源。</li></ul><h2 id="内存管理与视图卸载-🗑️" tabindex="-1">内存管理与视图卸载 🗑️ <a class="header-anchor" href="#内存管理与视图卸载-🗑️" aria-label="Permalink to &quot;内存管理与视图卸载 🗑️&quot;">​</a></h2><p>在某些情况下，为了释放内存，系统可能会卸载视图。理解这个过程对于避免内存泄漏至关重要。</p><ul><li><strong><code>didReceiveMemoryWarning()</code></strong>: 当系统内存不足时，会调用此方法。你可以在这里释放不必要的资源，例如缓存的图片或数据。</li><li><strong><code>viewWillUnload()</code> (已废弃)</strong>: 在iOS 6之前，当视图即将从内存中卸载时会调用此方法。现在，你主要依赖<code>didReceiveMemoryWarning()</code>来处理内存警告。</li><li><strong><code>viewDidUnload()</code> (已废弃)</strong>: 同样在iOS 6之前，当视图已经从内存中卸载时会调用此方法。现在，当控制器本身被释放时，其视图也会随之释放。</li></ul><blockquote><p>🚀 记住，<code>UIViewController</code>的生命周期是动态的。例如，当用户在应用之间切换时，<code>viewWillDisappear</code>和<code>viewDidDisappear</code>可能会被频繁调用。</p></blockquote><p>通过深入理解这些生命周期方法，你将能够编写出更高效、更稳定的iOS应用。每个方法都有其独特的职责，合理利用它们将大大提升你的开发效率和应用性能！</p>',18)]))}const w=o(l,[["render",a]]);export{p as __pageData,w as default};
